import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useTranslation } from 'react-i18next';
import '../styles/GuidePage.css';

export const GuidePage: React.FC = () => {
  const { completeGuide } = useAuth();
  const navigate = useNavigate();
  const { t } = useTranslation();
  const [currentStep, setCurrentStep] = useState(0);

  const steps = [
    {
      title: t('guide.step1'),
      description: t('guide.step1Desc'),
    },
    {
      title: t('guide.step2'),
      description: t('guide.step2Desc'),
    },
    {
      title: t('guide.step3'),
      description: t('guide.step3Desc'),
    },
  ];

  const handleNext = () => {
    if (currentStep < steps.length - 1) {
      setCurrentStep(currentStep + 1);
    } else {
      handleComplete();
    }
  };

  const handlePrev = () => {
    if (currentStep > 0) {
      setCurrentStep(currentStep - 1);
    }
  };

  const handleComplete = () => {
    completeGuide(); // 更新用户状态为已完成引导
    navigate('/dashboard'); // 跳转到仪表板
  };

  const handleSkip = () => {
    completeGuide(); // 即使跳过也标记为完成
    navigate('/dashboard');
  };

  return (
    <div className="guide-container">
      <div className="guide-content">
        <h1>{t('guide.welcome')}</h1>
        <p>{t('guide.welcomeMessage')}</p>
        
        <div className="step-indicator">
          {steps.map((_, index) => (
            <div
              key={index}
              className={`step-dot ${index === currentStep ? 'active' : ''}`}
              onClick={() => setCurrentStep(index)}
            />
          ))}
        </div>
        
        <div className="step-content">
          <h2>{steps[currentStep].title}</h2>
          <p>{steps[currentStep].description}</p>
        </div>
        
        <div className="guide-controls">
          <button 
            onClick={handleSkip} 
            className="skip-button"
          >
            {t('guide.skip')}
          </button>
          
          <div className="step-navigation">
            <button 
              onClick={handlePrev} 
              disabled={currentStep === 0}
              className="nav-button prev"
            >
              {t('common.prev')}
            </button>
            
            <button 
              onClick={handleNext}
              className="nav-button next"
            >
              {currentStep === steps.length - 1 ? t('guide.finish') : t('common.next')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};