import React, { useState, useEffect, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { Device } from '../types';
import { deviceAPI } from '../utils/api';
import { PageLayout } from '../components/PageLayout';
import { DeviceCard } from '../components/DeviceCard';
import { motion } from 'framer-motion';
import { PlusIcon, DiscIcon } from '../components/Icons';

export const DeviceManagementPage: React.FC = () => {
  const { t } = useTranslation();
  const [devices, setDevices] = useState<Device[]>([]);
  const [newDeviceCode, setNewDeviceCode] = useState(''); 
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>('');

  const fetchDevices = useCallback(async () => {
    try {
      const response = await deviceAPI.getDevices();
      if (response.data.code === 200) {
        // 处理Java后端返回的数据格式
        const deviceData = response.data.data || response.data;
        const deviceList = Array.isArray(deviceData.list) ? deviceData.list : deviceData;
        
        // 将Java后端的设备数据转换为前端格式
        const formattedDevices = deviceList.map((device: any) => ({
          id: device.id || device.deviceId,
          deviceId: device.deviceId,
          name: device.deviceName || device.name || t('device.unknownDevice', '未知设备'),
          status: device.state === '1' ? 'online' : 'offline', // 假设1表示在线
          userId: device.userId,
          createdAt: new Date(device.createTime || device.createdAt)
        }));
        
        setDevices(formattedDevices);
      } else {
        setError(response.data.msg || t('device.fetchFailed', '获取设备列表失败'));
      }
    } catch (err: any) {
      console.error('获取设备列表错误:', err);
      setError(err.response?.data?.msg || t('device.fetchFailedMessage', '获取设备列表失败，请稍后重试'));
    } finally {
      setLoading(false);
    }
  }, [t]);

  // 从API获取设备列表
  useEffect(() => {
    fetchDevices();
  }, [fetchDevices]);

  const handleBindDevice = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newDeviceCode.trim()) {
      setError(t('device.codeRequired', '请输入设备验证码'));
      return;
    }

    try {
      const response = await deviceAPI.bindDevice(newDeviceCode);
      
      if (response.data.code === 200) {
        // 绑定成功，刷新设备列表
        setNewDeviceCode('');
        setError('');
        alert(t('device.bindSuccess'));
        fetchDevices(); // 刷新设备列表
      } else {
        setError(response.data.msg || t('device.bindFailed', '绑定设备失败'));
      }
    } catch (err: any) {
      console.error('绑定设备错误:', err);
      setError(err.response?.data?.msg || t('device.bindFailedMessage', '绑定设备失败，请稍后重试'));
    }
  };

  const handleUnbindDevice = async (deviceId: string) => {
    if (!window.confirm(t('device.unbindConfirm', '确定要解绑此设备吗？'))) {
      return;
    }

    try {
      const response = await deviceAPI.unbindDevice(deviceId);
      
      if (response.data.code === 200) {
        // 解绑成功，刷新设备列表
        fetchDevices(); // 刷新设备列表
      } else {
        setError(response.data.msg || t('device.unbindFailed', '解绑设备失败'));
      }
    } catch (err: any) {
      console.error('解绑设备错误:', err);
      setError(err.response?.data?.msg || t('device.unbindFailedMessage', '解绑设备失败，请稍后重试'));
    }
  };

  if (loading) {
    return (
      <PageLayout title={t('device.title', '设备管理')}>
        <div className="flex justify-center items-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-500"></div>
        </div>
      </PageLayout>
    );
  }

  return (
    <PageLayout title={t('device.title', '设备管理')}>
      <div className="py-4">
        {error && (
          <motion.div 
            className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg mb-6"
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
          >
            {error}
          </motion.div>
        )}

        {/* 绑定新设备 */}
        <motion.div 
          className="bg-gradient-to-r from-blue-50 to-teal-50 rounded-2xl p-6 mb-8 shadow-lg border border-white/30"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.1 }}
        >
          <h2 className="text-2xl font-bold text-gray-800 mb-4 flex items-center">
            <PlusIcon className="mr-2 text-blue-500" />
            {t('device.bindDevice')}
          </h2>
          <form onSubmit={handleBindDevice} className="space-y-4">
            <div>
              <label htmlFor="deviceCode" className="block text-sm font-medium text-gray-700 mb-1">
                {t('device.verificationCode', '设备验证码')}
              </label>
              <input
                type="text"
                id="deviceCode"
                value={newDeviceCode}
                onChange={(e) => setNewDeviceCode(e.target.value)}
                placeholder={t('device.deviceIdPlaceholder', '输入设备验证码')}
                className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
                required
              />
            </div>
            <button 
              type="submit" 
              className="w-full md:w-auto px-6 py-3 bg-gradient-to-r from-blue-500 to-teal-400 text-white font-medium rounded-lg shadow-md hover:shadow-lg transition-all duration-300 hover:scale-105"
            >
              {t('device.bind')}
            </button>
          </form>
        </motion.div>

        {/* 设备列表 */}
        <motion.div 
          className="bg-white/80 backdrop-blur-sm rounded-2xl p-6 shadow-lg border border-white/30"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
        >
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-gray-800 flex items-center">
              <DiscIcon className="mr-2 text-teal-500" />
              {t('device.deviceList')}
            </h2>
            <span className="px-3 py-1 bg-blue-100 text-blue-800 rounded-full text-sm font-medium">
              {devices.length} {t('device.devices')}
            </span>
          </div>
          
          {devices.length === 0 ? (
            <div className="text-center py-12">
              <div className="text-gray-400 mb-4"> 
                <DiscIcon size={48} className="mx-auto" />
              </div>
              <p className="text-gray-600 text-lg">{t('device.noDevices', '暂无绑定设备')}</p>
              <p className="text-gray-500 mt-2">{t('device.noDevicesHint', '添加您的第一个设备开始使用')}</p>
            </div>
          ) : (
            <div className="space-y-4">
              {devices.map((device, index) => (
                <DeviceCard
                  key={device.id}
                  id={device.id}
                  name={device.name}
                  status={device.status}
                  deviceId={device.deviceId}
                  createdAt={device.createdAt}
                  onUnbind={handleUnbindDevice}
                />
              ))}
            </div>
          )}
        </motion.div>
      </div>
    </PageLayout>
  );
};