import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { useAuth } from '../contexts/AuthContext';
import { motion } from 'framer-motion';

export const Navigation: React.FC = () => {
  const { t } = useTranslation();
  const location = useLocation();
  const { logout } = useAuth();

  const navItems = [
    { path: '/dashboard', label: t('navigation.dashboard', '仪表板') },
    { path: '/devices', label: t('navigation.devices', '设备') },
    { path: '/profile', label: t('navigation.profile', '个人资料') }
  ];

  const handleLogout = () => {
    if (window.confirm(t('navigation.logoutConfirm', '确定要退出登录吗？'))) {
      logout();
    }
  };

  return (
    <motion.nav 
      className="fixed top-0 left-0 right-0 bg-white/30 backdrop-blur-lg border-b border-white/20 z-50 h-16 flex items-center justify-between px-6 shadow-sm"
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.3 }}
    >
      <div className="flex items-center space-x-10">
        <div className="flex items-center space-x-2">
          <div className="w-10 h-10 rounded-full bg-gradient-to-r from-blue-500 to-teal-400 flex items-center justify-center">
            <span className="text-white font-bold text-lg">M</span>
          </div>
          <Link to="/" className="text-2xl font-bold bg-gradient-to-r from-blue-600 to-purple-500 bg-clip-text text-transparent">
            MIRA
          </Link>
        </div>
        <div className="hidden md:flex space-x-6">
          {navItems.map(item => (
            <Link
              key={item.path}
              to={item.path}
              className={`px-3 py-2 rounded-lg transition-all duration-300 ${
                location.pathname === item.path 
                  ? 'bg-white/30 text-blue-600 shadow-inner' 
                  : 'text-gray-600 hover:text-blue-600 hover:bg-white/20'
              }`}
            >
              {item.label}
            </Link>
          ))}
        </div>
      </div>
      
      <div className="flex items-center space-x-4">
        <button 
          className="px-4 py-2 rounded-lg bg-gradient-to-r from-blue-500 to-teal-400 text-white font-medium shadow-md hover:shadow-lg transition-all duration-300 hover:scale-105"
          onClick={handleLogout}
        >
          {t('navigation.logout', '退出')}
        </button>
      </div>
    </motion.nav>
  );
};