import React from 'react';
import { Navigation } from '../components/Navigation';
import { motion } from 'framer-motion';

interface PageLayoutProps {
  title?: string;
  children: React.ReactNode;
  className?: string;
}

export const PageLayout: React.FC<PageLayoutProps> = ({ 
  title, 
  children, 
  className = '' 
}) => {
  return (
    <div className="min-h-screen bg-gradient-to-b from-blue-50 to-teal-50 pt-16">
      <Navigation />
      <main className="py-8">
        <div className="max-w-6xl mx-auto px-4">
          {title && (
            <motion.h1 
              className="text-4xl font-bold text-center mb-10 bg-gradient-to-r from-blue-600 to-teal-500 bg-clip-text text-transparent"
              initial={{ opacity: 0, y: -20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5 }}
            >
              {title}
            </motion.h1>
          )}
          <motion.div 
            className={`bg-white/60 backdrop-blur-sm rounded-2xl shadow-lg p-6 ${className}`}
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.3 }}
          >
            {children}
          </motion.div>
        </div>
      </main>
    </div>
  );
};