import React from 'react';
import { motion } from 'framer-motion';

interface CardProps {
  title: string;
  description: string;
  icon?: React.ReactNode;
  onClick?: () => void;
  className?: string;
}

export const Card: React.FC<CardProps> = ({ 
  title, 
  description, 
  icon, 
  onClick,
  className = '' 
}) => {
  return (
    <motion.div
      className={`bg-white/80 backdrop-blur-sm rounded-xl p-6 shadow-lg border border-white/30 cursor-pointer transition-all duration-300 hover:shadow-xl hover:scale-[1.02] ${className}`}
      whileHover={{ y: -5 }}
      whileTap={{ scale: 0.98 }}
      onClick={onClick}
      style={{ minHeight: '200px' }}
    >
      {icon && <div className="mb-4 flex justify-center">{icon}</div>}
      <h3 className="text-2xl font-bold text-center text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-teal-500 mb-3">
        {title}
      </h3>
      <p className="text-gray-600 text-center">
        {description}
      </p>
    </motion.div>
  );
};