import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { UserIcon, CameraIcon } from './Icons';

interface ProfileCardProps {
  name: string;
  email: string;
  avatar?: string;
  onAvatarChange?: (file: File) => void;
}

export const ProfileCard: React.FC<ProfileCardProps> = ({ 
  name, 
  email, 
  avatar, 
  onAvatarChange 
}) => {
  const [preview, setPreview] = useState<string | null>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const filePreview = URL.createObjectURL(file);
      setPreview(filePreview);
      
      if (onAvatarChange) {
        onAvatarChange(file);
      }
    }
  };

  return (
    <motion.div 
      className="bg-white/80 backdrop-blur-sm rounded-2xl p-8 shadow-lg border border-white/30 text-center"
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      transition={{ duration: 0.3 }}
    >
      <div className="flex flex-col items-center">
        <div className="relative group">
          <div className="w-24 h-24 rounded-full bg-gradient-to-r from-blue-100 to-teal-100 flex items-center justify-center overflow-hidden border-4 border-white shadow-lg">
            {preview ? (
              <img 
                src={preview} 
                alt="Avatar preview" 
                className="w-full h-full object-cover"
              />
            ) : avatar ? (
              <img 
                src={avatar} 
                alt="User avatar" 
                className="w-full h-full object-cover"
              />
            ) : (
              <UserIcon className="w-12 h-12 text-blue-500" />
            )}
          </div>
          <label className="absolute bottom-0 right-0 bg-gradient-to-r from-blue-500 to-teal-400 p-2 rounded-full cursor-pointer group-hover:scale-110 transition-transform shadow-md">
            <CameraIcon className="w-4 h-4 text-white" />
            <input 
              type="file" 
              className="hidden" 
              accept="image/*"
              onChange={handleFileChange}
            />
          </label>
        </div>
        
        <div className="mt-6 text-left w-full max-w-md">
          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 mb-1">姓名</label>
            <div className="px-4 py-3 bg-gray-50 rounded-lg text-gray-800 font-medium">
              {name}
            </div>
          </div>
          
          <div className="mb-6">
            <label className="block text-sm font-medium text-gray-700 mb-1">邮箱</label>
            <div className="px-4 py-3 bg-gray-50 rounded-lg text-gray-800 font-medium">
              {email}
            </div>
          </div>
        </div>
      </div>
    </motion.div>
  );
};