import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { authAPI } from '../utils/api';
import { useTranslation } from 'react-i18next';
import { PageLayout } from '../components/PageLayout';
import { ProfileCard } from '../components/ProfileCard';
import { motion } from 'framer-motion';
import { staggerContainer, fadeInUp } from '../utils/animations';

export const ProfilePage: React.FC = () => {
  const { state, updateUser } = useAuth();
  const { t } = useTranslation();
  const [formData, setFormData] = useState({
    currentName: '',  // 只读姓名
    currentEmail: '',
    password: '',
    confirmPassword: ''
  });
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  // Note: avatarFile is stored but not yet implemented in the API call
  const [loading, setLoading] = useState(true);
  const [updateSuccess, setUpdateSuccess] = useState(false);
  const [error, setError] = useState('');

  // 初始化表单数据
  useEffect(() => {
    const fetchProfile = async () => {
      try {
        const response = await authAPI.getProfile();
        if (response.data && response.data.code === 200) {
          const userData = response.data.data || response.data;
          setFormData(prev => ({
            ...prev,
            currentName: userData.name || userData.username || userData.id || '未知用户',
            currentEmail: userData.email || userData.username || '未设置邮箱'
          }));
        } else {
          setError(response.data.msg || t('profile.loadFailed', '加载用户信息失败'));
        }
      } catch (err: any) {
        console.error('获取用户资料错误:', err);
        setError(err.response?.data?.msg || t('profile.loadFailedMessage', '加载用户信息失败，请稍后重试'));
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, [t]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleAvatarChange = (file: File) => {
    setAvatarFile(file);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setUpdateSuccess(false);

    // 验证密码匹配
    if (formData.password && formData.password !== formData.confirmPassword) {
      setError(t('profile.passwordMismatch', '密码和确认密码不匹配'));
      return;
    }

    try {
      // 只发送密码字段到后端
      const profileData: any = {};
      if (formData.password) {
        profileData.password = formData.password;
      }

      const response = await authAPI.updateUserProfile(profileData);

      if (response.data && response.data.code === 200) {
        setUpdateSuccess(true);
        
        // 更新上下文中的用户信息
        if (state.user) {
          const updatedUser = {
            ...state.user
            // 姓名不更新，因为现在是只读的
          };
          
          updateUser(updatedUser);
        }
        
        // 重置密码字段
        setFormData(prev => ({
          ...prev,
          password: '',
          confirmPassword: ''
        }));
        
        // 3秒后隐藏成功消息
        setTimeout(() => setUpdateSuccess(false), 3000);
      } else {
        setError(response.data.msg || t('profile.updateFailed', '更新失败'));
      }
    } catch (err: any) {
      console.error('更新用户信息错误:', err);
      setError(err.response?.data?.msg || t('profile.updateFailedMessage', '更新失败，请稍后重试'));
    }
  };

  if (loading) {
    return (
      <PageLayout title={t('profile.title', '个人资料')}>
        <div className="flex justify-center items-center h-64">
          <motion.div 
            className="w-12 h-12 border-t-4 border-blue-500 border-solid rounded-full"
            animate={{ rotate: 360 }}
            transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
          />
        </div>
      </PageLayout>
    );
  }

  return (
    <PageLayout title={t('profile.title', '个人资料')}>
      <motion.div 
        className="py-4"
        variants={staggerContainer}
        initial="hidden"
        animate="visible"
      >
        {updateSuccess && (
          <motion.div 
            className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-lg mb-6"
            initial={{ opacity: 0, y: -20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            transition={{ duration: 0.3 }}
          >
            {t('profile.updateSuccess', '个人资料更新成功!')}
          </motion.div>
        )}
        
        {error && (
          <motion.div 
            className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg mb-6"
            initial={{ opacity: 0, y: -20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            transition={{ duration: 0.3 }}
          >
            {error}
          </motion.div>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <motion.div 
            className="lg:col-span-1"
            variants={fadeInUp}
          >
            <ProfileCard 
              name={formData.currentName} 
              email={formData.currentEmail} 
              onAvatarChange={handleAvatarChange}
            />
          </motion.div>
          
          <motion.div 
            className="lg:col-span-2"
            variants={fadeInUp}
          >
            <motion.div 
              className="bg-white/80 backdrop-blur-sm rounded-2xl p-8 shadow-lg border border-white/30"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: 0.2 }}
            >
              <h2 className="text-2xl font-bold text-gray-800 mb-6">{t('profile.editProfile', '编辑资料')}</h2>
              <motion.form 
                onSubmit={handleSubmit} 
                className="space-y-6"
                variants={staggerContainer}
                initial="hidden"
                animate="visible"
              >
                <motion.div variants={fadeInUp}>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    {t('profile.name', '姓名')}
                  </label>
                  <input
                    type="text"
                    value={formData.currentName}
                    readOnly
                    className="w-full px-4 py-3 rounded-lg border border-gray-200 bg-gray-50 text-gray-600 cursor-not-allowed"
                  />
                </motion.div>

                <motion.div variants={fadeInUp}>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    {t('profile.email', '邮箱')}
                  </label>
                  <input
                    type="email"
                    value={formData.currentEmail}
                    readOnly
                    className="w-full px-4 py-3 rounded-lg border border-gray-200 bg-gray-50 text-gray-600 cursor-not-allowed"
                  />
                </motion.div>

                <motion.div variants={fadeInUp}>
                  <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-1">
                    {t('profile.newPassword', '新密码')}
                  </label>
                  <input
                    type="password"
                    id="password"
                    name="password"
                    value={formData.password}
                    onChange={handleChange}
                    placeholder={t('profile.passwordPlaceholder', '留空则不修改密码')}
                    className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
                  />
                </motion.div>

                <motion.div variants={fadeInUp}>
                  <label htmlFor="confirmPassword" className="block text-sm font-medium text-gray-700 mb-1">
                    {t('profile.confirmPassword', '确认密码')}
                  </label>
                  <input
                    type="password"
                    id="confirmPassword"
                    name="confirmPassword"
                    value={formData.confirmPassword}
                    onChange={handleChange}
                    placeholder={t('profile.confirmPasswordPlaceholder', '确认新密码')}
                    className="w-full px-4 py-3 rounded-lg border border-gray-300 focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
                  />
                </motion.div>

                <motion.button 
                  type="submit" 
                  className="w-full md:w-auto px-6 py-3 bg-gradient-to-r from-blue-500 to-teal-400 text-white font-medium rounded-lg shadow-md hover:shadow-lg transition-all duration-300 hover:scale-105"
                  whileHover={{ scale: 1.03 }}
                  whileTap={{ scale: 0.98 }}
                >
                  {t('profile.updateButton', '更新资料')}
                </motion.button>
              </motion.form>
            </motion.div>
          </motion.div>
        </div>
      </motion.div>
    </PageLayout>
  );
};